{
  "items": [
    {
      "name": "exists_gcd_eq_mul_add_mul",
      "module_name": "Mathlib.RingTheory.PrincipalIdealDomain",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] [IsBezout R] [IsDomain R] [inst_3 : GCDMonoid R] (a b : R),\n  ∃ x y, gcd a b = a * x + b * y"
    },
    {
      "name": "Int.gcd_eq_gcd_ab",
      "module_name": "Mathlib.Data.Int.GCD",
      "kind": "theorem",
      "type": "∀ (x y : ℤ), ↑(x.gcd y) = x * x.gcdA y + y * x.gcdB y"
    },
    {
      "name": "gcd_dvd_iff_exists",
      "module_name": "Mathlib.RingTheory.PrincipalIdealDomain",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] [IsBezout R] [IsDomain R] [inst_3 : GCDMonoid R] (a b : R) {z : R},\n  gcd a b ∣ z ↔ ∃ x y, z = a * x + b * y"
    },
    {
      "name": "IsBezout.gcd_eq_sum",
      "module_name": "Mathlib.RingTheory.PrincipalIdealDomain",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] (x y : R) [inst_1 : Submodule.IsPrincipal (Ideal.span {x, y})],\n  ∃ a b, a * x + b * y = IsBezout.gcd x y"
    },
    {
      "name": "EuclideanDomain.gcd_eq_gcd_ab",
      "module_name": "Mathlib.Algebra.EuclideanDomain.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : EuclideanDomain R] [inst_1 : DecidableEq R] (a b : R),\n  EuclideanDomain.gcd a b = a * EuclideanDomain.gcdA a b + b * EuclideanDomain.gcdB a b"
    },
    {
      "name": "Nat.gcd_eq_gcd_ab",
      "module_name": "Mathlib.Data.Int.GCD",
      "kind": "theorem",
      "type": "∀ (x y : ℕ), ↑(x.gcd y) = ↑x * x.gcdA y + ↑y * x.gcdB y"
    },
    {
      "name": "IsBezout.gcd",
      "module_name": "Mathlib.RingTheory.PrincipalIdealDomain",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Ring R] → (x y : R) → [Submodule.IsPrincipal (Ideal.span {x, y})] → R"
    },
    {
      "name": "PNat.gcd_b_eq",
      "module_name": "Mathlib.Data.PNat.Xgcd",
      "kind": "theorem",
      "type": "∀ (a b : ℕ+), b = a.gcdB' b * a.gcd b"
    }
  ]
}
